class Student {
    String name;
    int age;
    String course;

    void displayProfile() {
        System.out.println("Student: " + name + " | Age: " + age + " | Course: " + course);
    }
}

public class Main {
    public static void main(String[] args) {
        // Create object #1
        Student s1 = new Student();
        s1.name = "Rahul";
        s1.age = 20;
        s1.course = "Java";

        // Create object #2 from the EXACT same blueprint
        Student s2 = new Student();
        s2.name = "Priya";
        s2.age = 21;
        s2.course = "Python";

        // Call their behaviors:
        s1.displayProfile();
        s2.displayProfile();
    }
}

