class Rectangle {
    int length;
    int width;

    void printPerimeter() {
        int p = 2 * (length + width);
        System.out.println("Perimeter: " + p);
    }
}

public class Main {
    public static void main(String[] args) {
        Rectangle r = new Rectangle();
        r.length = 8;
        r.width = 5;
        r.printPerimeter();
    }
}

